            if($order['payment_status']!=='paid'||(!in_array($order['audit_status'],['pending','supplement_required'],true)&&!$auto))throw new RuntimeException('该订单不在可审核或自动预审抽查状态。');if($auto&&$decision==='approve')throw new RuntimeException('该订单已自动预审通过，无需重复审核通过。');if(!empty($order['selected_quote_id']))throw new RuntimeException('用户已选择报价的订单不能重新审核，请使用取消或争议处理流程。');
            if($decision==='approve'){
