                $db->execute("UPDATE orders SET audit_status='approved',audit_note=:reason,supplement_due_at=NULL,audited_at=NOW(),publish_status=:publish,lifecycle_status='active',published_at=:published,quote_deadline_at=COALESCE(quote_deadline_at,DATE_ADD(NOW(),INTERVAL {$autoCancelDays} DAY)),version=version+1,updated_at=NOW() WHERE id=:id",['reason'=>$reason?:null,'publish'=>$linked?'hidden':'published','published'=>$linked?null:gmdate('Y-m-d H:i:s'),'id'=>$id]);
                $db->execute("UPDATE order_deadlines SET status='completed',processed_at=NOW(),updated_at=NOW() WHERE order_id=:id AND deadline_type='audit_supplement_timeout' AND status IN ('pending','blocked','claimed')",['id'=>$id]);$db->execute("UPDATE order_deadlines SET status='cancelled',processed_at=NOW(),updated_at=NOW() WHERE order_id=:id AND deadline_type='quote_expiry' AND status='pending'",['id'=>$id]);$db->execute("INSERT INTO order_deadlines(order_id,deadline_type,status,version,due_at,created_at,updated_at) SELECT id,'quote_expiry','pending',version,quote_deadline_at,NOW(),NOW() FROM orders WHERE id=:id",['id'=>$id]);$this->events->record($id,'audit_approve',$adminId,$reason);return null;
            }
            if($decision==='supplement'){
                $db->execute("UPDATE orders SET audit_status='supplement_required',audit_note=:reason,supplement_due_at=DATE_ADD(NOW(),INTERVAL {$supplementHours} HOUR),audited_at=NOW(),publish_status='hidden',quote_status='waiting',quote_deadline_at=NULL,version=version+1,updated_at=NOW() WHERE id=:id",['reason'=>$reason,'id'=>$id]);if($auto){$db->execute("UPDATE quotes SET status='cancelled',updated_at=NOW() WHERE order_id=:id AND status='active'",['id'=>$id]);$db->execute("UPDATE order_deadlines SET status='cancelled',processed_at=NOW(),updated_at=NOW() WHERE order_id=:id AND deadline_type='quote_expiry' AND status IN ('pending','blocked','claimed')",['id'=>$id]);$this->events->record($id,'auto_preapproval_reopened',$adminId,'自动预审抽查发现需补资料：'.$reason);}$db->execute("UPDATE order_deadlines SET status='cancelled',processed_at=NOW(),updated_at=NOW() WHERE order_id=:id AND deadline_type='audit_supplement_timeout' AND status IN ('pending','blocked','claimed')",['id'=>$id]);$db->execute("INSERT INTO order_deadlines(order_id,deadline_type,status,version,due_at,created_at,updated_at) SELECT id,'audit_supplement_timeout','pending',version,supplement_due_at,NOW(),NOW() FROM orders WHERE id=:id",['id'=>$id]);$this->events->record($id,'audit_supplement',$adminId,$reason);return null;
            }
            $payment=$db->fetch("SELECT id,amount_cents FROM payment_orders WHERE order_id=:id AND business_type IN ('order_booking','booking_fee') AND status='paid' ORDER BY id DESC LIMIT 1 FOR UPDATE",['id'=>$id]);$bookingCap=$payment?((int)$order['booking_fee_cents']>0?min((int)$payment['amount_cents'],(int)$order['booking_fee_cents']):(int)$payment['amount_cents']):0;$alloc=$payment?$this->paymentAllocations($db,(int)$payment['id'],$id):['refund'=>0,'outstanding'=>0,'runner'=>0];$refund=max(0,$bookingCap-$alloc['refund']-$alloc['runner']);$outstanding=$alloc['outstanding']+$refund;
            (new DatabaseOrderCancellationRiskRepository($db))->captureCancellation($order);
