            $request=$db->insert("INSERT INTO order_cancel_requests(public_id,order_id,applicant_type,applicant_id,request_type,order_state_snapshot_json,reason_code,reason,status,requested_refund_cents,requested_at,closed_at,created_at,updated_at) VALUES(:public_id,:order_id,'admin',:admin,'audit_reject',:snapshot,'audit_rejected',:reason,'approved',:refund,NOW(),IF(:close=1,NOW(),NULL),NOW(),NOW())",['public_id'=>\public_id(),'order_id'=>$id,'admin'=>$adminId,'snapshot'=>json_encode($order,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES),'reason'=>$reason,'refund'=>$refund,'close'=>$outstanding>0?0:1]);$rid=null;if($refund>0&&$payment)$rid=$db->insert("INSERT INTO refunds(public_no,payment_order_id,order_id,cancel_request_id,amount_cents,reason,status,requested_by_admin_id,requested_at,created_at,updated_at) VALUES(:no,:payment,:order,:request,:amount,:reason,'pending_review',:admin,NOW(),NOW(),NOW())",['no'=>\business_no('RF'),'payment'=>$payment['id'],'order'=>$id,'request'=>$request,'amount'=>$refund,'reason'=>'审核驳回，订单自动取消：'.$reason,'admin'=>$adminId]);$db->insert("INSERT INTO order_cancel_decisions(cancel_request_id,order_id,decision,responsibility,reason,refund_amount_cents,run_empty_fee_cents,refund_id,decided_by,decided_at,created_at) VALUES(:request,:order,'approved','platform',:reason,:refund,0,:rid,:admin,NOW(),NOW())",['request'=>$request,'order'=>$id,'reason'=>$reason,'refund'=>$refund,'rid'=>$rid,'admin'=>$adminId]);$this->events->record($id,'admin_cancelled',$adminId,'审核驳回，订单已取消并进入退款流程：'.$reason);return $rid;
        });
