        return ['before'=>$before,'after'=>$this->db->fetch('SELECT * FROM orders WHERE id=:id',['id'=>$id]),'refund_id'=>$refundId,'message'=>$message];
    }

    public function cancel(int $id,string $reason,int $adminId): array
    {
        if(mb_strlen($reason)<2)throw new RuntimeException('请填写取消原因。');return $this->db->transaction(function(Database $db)use($id,$reason,$adminId){
            if (function_exists('app_config') && \app_config('chat.order_policy_enabled',false)===true) {
                (new DatabaseOrderConversationBridge($db,true))->schedule($id);
            }
$order=$db->fetch('SELECT * FROM orders WHERE id=:id FOR UPDATE',['id'=>$id]);if(!$order)throw new RuntimeException('订单不存在。');if($this->terminal((string)$order['lifecycle_status']))throw new RuntimeException('当前订单状态不能重复取消。');$payments=$this->refundablePayments($db,$order);$refund=array_sum(array_column($payments,'available_cents'));(new DatabaseOrderCancellationRiskRepository($db))->captureCancellation($order);$db->execute("UPDATE orders SET lifecycle_status=:life,publish_status='hidden',quote_status='cancelled',assignment_status='cancelled',fulfillment_status='cancelled',refund_status=:refund_status,cancelled_at=NOW(),closed_at=IF(:close=1,COALESCE(closed_at,NOW()),closed_at),updated_at=NOW(),version=version+1 WHERE id=:id",['life'=>$refund>0?'cancel_approved_pending_refund':'cancelled','refund_status'=>$refund>0?'pending_review':'none','close'=>$refund>0?0:1,'id'=>$id]);$this->cancelDependents($db,$id);$request=$db->insert("INSERT INTO order_cancel_requests(public_id,order_id,applicant_type,applicant_id,request_type,order_state_snapshot_json,reason_code,reason,status,requested_refund_cents,requested_at,closed_at,created_at,updated_at) VALUES(:public_id,:order_id,'admin',:admin,'forced_cancel_refund',:snapshot,'admin_forced',:reason,:status,:refund,NOW(),IF(:close=1,NOW(),NULL),NOW(),NOW())",['public_id'=>\public_id(),'order_id'=>$id,'admin'=>$adminId>0?$adminId:null,'snapshot'=>json_encode($order,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES),'reason'=>$reason,'status'=>$refund>0?'processing':'approved','refund'=>$refund,'close'=>$refund>0?0:1]);$ids=[];$first=null;foreach($payments as $payment){$part=(int)$payment['available_cents'];if($part<1)continue;$rid=$db->insert("INSERT INTO refunds(public_no,payment_order_id,order_id,cancel_request_id,amount_cents,reason,status,requested_by_admin_id,requested_at,created_at,updated_at) VALUES(:no,:payment,:order,:request,:amount,:reason,'pending_review',:admin,NOW(),NOW(),NOW())",['no'=>\business_no('RF'),'payment'=>$payment['id'],'order'=>$id,'request'=>$request,'amount'=>$part,'reason'=>$reason.'；原支付：'.$payment['business_type'],'admin'=>$adminId>0?$adminId:null]);if($first===null)$first=$rid;$ids[]=$rid;}$db->insert("INSERT INTO order_cancel_decisions(cancel_request_id,order_id,decision,responsibility,reason,refund_amount_cents,run_empty_fee_cents,refund_id,decided_by,decided_at,created_at) VALUES(:request,:order,'approved','platform',:reason,:refund,0,:rid,:admin,NOW(),NOW())",['request'=>$request,'order'=>$id,'reason'=>$reason,'refund'=>$refund,'rid'=>$first,'admin'=>$adminId>0?$adminId:null]);$this->events->record($id,'admin_cancelled',$adminId,$refund>0?('管理员强制取消，已按原支付拆分 '.$refund.' 分退款，共 '.count($ids).' 笔'):$reason);return ['refund_cents'=>$refund,'refund_count'=>count($ids)];});
    }

    public function invite(int $id,array $in,int $adminId): array
    {
        $shareType=(string)($in['share_type']??'')==='ordinary'?'ordinary':'worker_invite';if($shareType==='ordinary'){$order=$this->db->fetch("SELECT id,public_no,audit_status,publish_status,lifecycle_status,selected_quote_id FROM orders WHERE id=:id",['id'=>$id]);if(!$order||$order['audit_status']!=='approved'||$order['publish_status']!=='published'||$order['lifecycle_status']!=='active'||!empty($order['selected_quote_id']))throw new RuntimeException('普通分享仅适用于已审核、正在大厅公开且尚未接受报价的订单。');$token=rtrim(strtr(base64_encode(random_bytes(24)),'+/','-_'),'=');$expires=gmdate('Y-m-d H:i:s',time()+7*86400);$share=$this->db->insert("INSERT INTO share_contexts(order_id,context_type,token_hash,created_by_type,created_by_id,snapshot_json,status,expires_at,created_at) VALUES(:order,'ordinary_order',:hash,'admin',:admin,:snapshot,'active',:expires,NOW())",['order'=>$id,'hash'=>hash('sha256',$token),'admin'=>$adminId,'snapshot'=>json_encode(['public_no'=>$order['public_no']],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES),'expires'=>$expires]);$payload='/pages/workerOrder/detail?id='.rawurlencode($order['public_no']).'&share=ordinary&share_token='.rawurlencode($token);return $this->withCode(['order_id'=>$id,'invite_id'=>$share,'share_type'=>'ordinary','token'=>$token,'payload'=>$payload,'expires_at'=>$expires],$id,'ordinary');}
        $rate=max(0,min(10000,(int)round(((float)($in['commission_rate']??10))*100)));$days=max(1,min(30,(int)($in['valid_days']??7)));$reason=trim((string)($in['reason']??''))?:'管理员分享订单给受邀师傅';$token=rtrim(strtr(base64_encode(random_bytes(32)),'+/','-_'),'=');$hash=hash('sha256',$token);$expires=gmdate('Y-m-d H:i:s',time()+$days*86400);
        $invite=$this->db->transaction(function(Database $db)use($id,$rate,$reason,$hash,$expires,$adminId){$order=$db->fetch('SELECT * FROM orders WHERE id=:id FOR UPDATE',['id'=>$id]);if(!$order||$order['lifecycle_status']!=='active'||$order['audit_status']!=='approved')throw new RuntimeException('只有审核通过且进行中的订单可以生成师傅邀请。');$minimum=max(1,(int)$order['commission_min_cents']);$quote=!empty($order['selected_quote_id'])?$db->fetch("SELECT q.id,q.quote_type,q.status,s.amount_cents_snapshot,s.booking_fee_cents_snapshot,s.status AS selection_status FROM quotes q INNER JOIN quote_selections s ON s.quote_id=q.id AND s.order_id=q.order_id WHERE q.id=:quote AND q.order_id=:order AND s.status IN ('confirmed','paid') ORDER BY s.id DESC LIMIT 1 FOR UPDATE",['quote'=>$order['selected_quote_id'],'order'=>$id]):null;$payment=$db->fetch("SELECT id,amount_cents FROM payment_orders WHERE order_id=:id AND business_type IN ('order_booking','booking_fee') AND status='paid' ORDER BY id DESC LIMIT 1 FOR UPDATE",['id'=>$id]);if(!$quote||$quote['quote_type']!=='platform'||!in_array($quote['status'],['selected','active'],true)||$order['payment_status']!=='paid'||!$payment)throw new RuntimeException('用户接受平台报价并支付本单预约费后，才能分享给受邀师傅。');if((int)$quote['amount_cents_snapshot']!==(int)$order['final_amount_cents']||(int)$quote['booking_fee_cents_snapshot']!==(int)$order['booking_fee_cents']||(int)$payment['amount_cents']<(int)$quote['booking_fee_cents_snapshot'])throw new RuntimeException('订单金额、报价快照和实付预约费不一致，请先核对支付记录。');if($db->fetchValue("SELECT COUNT(*) FROM assignments WHERE order_id=:id AND status='accepted'",['id'=>$id])>0)throw new RuntimeException('已有师傅接单，不能继续生成邀请。');$db->execute("UPDATE invite_tokens SET status='revoked' WHERE order_id=:id AND status='active'",['id'=>$id]);$db->execute("UPDATE assignments SET status='cancelled',cancelled_at=NOW(),updated_at=NOW() WHERE order_id=:id AND status='offered'",['id'=>$id]);$version=(int)$db->fetchValue('SELECT COALESCE(MAX(version_no),0)+1 FROM commission_rule_versions WHERE order_id=:id',['id'=>$id]);$db->execute("UPDATE commission_rule_versions SET status='superseded' WHERE order_id=:id AND status='active'",['id'=>$id]);$rule=$db->insert("INSERT INTO commission_rule_versions(order_id,version_no,rate_bp,min_fee_cents,adjustment_type,adjustment_reason,created_by_admin_id,status,created_at) VALUES(:id,:version,:rate,:minimum,'invite_adjustment',:reason,:admin,'active',NOW())",['id'=>$id,'version'=>$version,'rate'=>$rate,'minimum'=>$minimum,'reason'=>$reason,'admin'=>$adminId]);$inviteId=$db->insert("INSERT INTO invite_tokens(order_id,token_hash,purpose,created_by_admin_id,commission_rule_version_id,status,max_claims,claim_count,expires_at,created_at) VALUES(:id,:hash,'worker_assignment',:admin,:rule,'active',1,0,:expires,NOW())",['id'=>$id,'hash'=>$hash,'admin'=>$adminId,'rule'=>$rule,'expires'=>$expires]);$db->execute("UPDATE orders SET commission_rate_bp=:rate,commission_min_cents=:minimum,commission_rule_version_id=:rule,updated_at=NOW(),version=version+1 WHERE id=:id",['rate'=>$rate,'minimum'=>$minimum,'rule'=>$rule,'id'=>$id]);$this->events->record($id,'worker_invite_created',$adminId,'管理员生成受邀师傅口令，有效期 '.$expires);return $inviteId;});$payload='/pages/workerOrder/detail?invite='.rawurlencode($token);return $this->withCode(['order_id'=>$id,'invite_id'=>$invite,'share_type'=>'worker_invite','token'=>$token,'payload'=>$payload,'expires_at'=>$expires],$id,'worker_invite');
    }

    private function withCode(array $result,int $id,string $type): array {if(!$this->generateCode){$result['code_skipped']='testing adapter: no external mini-program code';return$result;}try{$result['code_data_uri']=(new MiniProgramCodeService())->generate($id,$type,$result['payload'])['data_uri'];}catch(Throwable $e){$result['code_error']=$e->getMessage();}return$result;}
    private function cancelDependents(Database $db,int $id): void {$db->execute("UPDATE quotes SET status='cancelled',updated_at=NOW() WHERE order_id=:id AND status IN ('active','selected')",['id'=>$id]);$db->execute("UPDATE assignments SET status='cancelled',cancelled_at=NOW(),updated_at=NOW() WHERE order_id=:id AND status IN ('offered','accepted')",['id'=>$id]);$db->execute("UPDATE invite_tokens SET status='revoked' WHERE order_id=:id AND status='active'",['id'=>$id]);$db->execute("UPDATE order_role_grants SET status='revoked',revoked_at=NOW() WHERE order_id=:id AND status='active'",['id'=>$id]);$db->execute("UPDATE order_deadlines SET status='cancelled',processed_at=NOW(),updated_at=NOW() WHERE order_id=:id AND status IN ('pending','blocked','claimed')",['id'=>$id]);}
    private function paymentAllocations(Database $db,int $paymentId,int $orderId): array {$refundRows=$db->fetchAll("SELECT amount_cents,status FROM refunds WHERE payment_order_id=:id AND status NOT IN ('failed','closed','cancelled','rejected') FOR UPDATE",['id'=>$paymentId]);$refund=0;$outstanding=0;foreach($refundRows as $r){$refund+=(int)$r['amount_cents'];if(!in_array($r['status'],['succeeded','refunded'],true))$outstanding+=(int)$r['amount_cents'];}$runner=(int)$db->fetchValue("SELECT COALESCE(SUM(l.amount_cents),0) FROM worker_balance_ledger l INNER JOIN disputes d ON d.id=l.business_id WHERE l.business_type='dispute' AND l.entry_type='run_empty_fee' AND l.status='effective' AND d.order_id=:id",['id'=>$orderId]);return ['refund'=>$refund,'outstanding'=>$outstanding,'runner'=>$runner];}
    private function refundablePayments(Database $db,array $order): array {$types=(string)($order['workflow_profile']??'construction')==='measurement'?['order_booking','booking_fee','measurement_balance','measurement_change']:['order_booking','booking_fee'];$marks=[];$params=['id'=>$order['id']];foreach($types as $i=>$type){$marks[]=':t'.$i;$params['t'.$i]=$type;}$rows=$db->fetchAll("SELECT * FROM payment_orders WHERE order_id=:id AND status IN ('paid','refunded') AND business_type IN (".implode(',',$marks).') ORDER BY id FOR UPDATE',$params);$runner=(int)$db->fetchValue("SELECT COALESCE(SUM(l.amount_cents),0) FROM worker_balance_ledger l INNER JOIN disputes d ON d.id=l.business_id WHERE l.business_type='dispute' AND l.entry_type='run_empty_fee' AND l.status='effective' AND d.order_id=:id",['id'=>$order['id']]);$result=[];foreach($rows as $row){$allocated=(int)$db->fetchValue("SELECT COALESCE(SUM(amount_cents),0) FROM refunds WHERE payment_order_id=:id AND status NOT IN ('failed','closed','cancelled','rejected')",['id'=>$row['id']]);$available=max(0,(int)$row['amount_cents']-$allocated);if($runner>0){$deduct=min($runner,$available);$available-=$deduct;$runner-=$deduct;}if($available>0){$row['available_cents']=$available;$result[]=$row;}}return$result;}
    private function terminal(string $status): bool {return in_array($status,['cancelled','completed','closed','cancel_approved_pending_refund','refunded'],true);}
}

